70:  *
71:  * returns NULL in case the allocation wasn't moved.
72:  * when it returns a non-null value, the old pointer was already released
73:  * and should NOT be accessed. */
74: sds activeDefragSds(sds sdsptr) {
75:     void* ptr = sdsAllocPtr(sdsptr);
76:     void* newptr = activeDefragAlloc(ptr);
77:     if (newptr) {
78:         size_t offset = sdsptr - (char*)ptr;
79:         sdsptr = (char*)newptr + offset;
80:         return sdsptr;
