102:  *
103:  * Like activeDefragStringOb, but it requires the caller to pass in the expected
104:  * reference count. In some cases, the caller needs to update a robj whose
105:  * reference count is not 1, in these cases, the caller must explicitly pass
106:  * in the reference count, otherwise defragmentation will not be performed.
107:  * Note that the caller is responsible for updating any other references to the robj. */
108: robj *activeDefragStringObEx(robj* ob, int expected_refcount) {
109:     robj *ret = NULL;
110:     if (ob->refcount!=expected_refcount)
111:         return NULL;
112: 
113:     /* try to defrag robj (only if not an EMBSTR type (handled below). */
114:     if (ob->type!=OBJ_STRING || ob->encoding!=OBJ_ENCODING_EMBSTR) {
115:         if ((ret = activeDefragAlloc(ob))) {
116:             ob = ret;
117:         }
118:     }
119: 
120:     /* try to defrag string object */
121:     if (ob->type == OBJ_STRING) {
122:         if(ob->encoding==OBJ_ENCODING_RAW) {
123:             sds newsds = activeDefragSds((sds)ob->ptr);
124:             if (newsds) {
125:                 ob->ptr = newsds;
126:             }
127:         } else if (ob->encoding==OBJ_ENCODING_EMBSTR) {
128:             /* The sds is embedded in the object allocation, calculate the
129:              * offset and update the pointer in the new allocation. */
130:             long ofs = (intptr_t)ob->ptr - (intptr_t)ob;
131:             if ((ret = activeDefragAlloc(ob))) {
132:                 ret->ptr = (void*)((intptr_t)ret + ofs);
133:             }
134:         } else if (ob->encoding!=OBJ_ENCODING_INT) {
135:             serverPanic("Unknown string encoding");
136:         }
137:     }
138:     return ret;
139: }
