198: void zslUpdateNode(zskiplist *zsl, zskiplistNode *oldnode, zskiplistNode *newnode, zskiplistNode **update) {
199:     int i;
200:     for (i = 0; i < zsl->level; i++) {
201:         if (update[i]->level[i].forward == oldnode)
202:             update[i]->level[i].forward = newnode;
203:     }
204:     serverAssert(zsl->header!=oldnode);
205:     if (newnode->level[0].forward) {
206:         serverAssert(newnode->level[0].forward->backward==oldnode);
207:         newnode->level[0].forward->backward = newnode;
208:     } else {
209:         serverAssert(zsl->tail==oldnode);
210:         zsl->tail = newnode;
211:     }
