836: /* Defrag scan callback for the main db dictionary. */
837: void defragScanCallback(void *privdata, const dictEntry *de) {
838:     long long hits_before = server.stat_active_defrag_hits;
839:     defragKey((defragCtx*)privdata, (dictEntry*)de);
840:     if (server.stat_active_defrag_hits != hits_before)
841:         server.stat_active_defrag_key_hits++;
842:     else
