881: /* Defrag scan callback for the pubsub dictionary. */
882: void defragPubsubScanCallback(void *privdata, const dictEntry *de) {
883:     defragCtx *ctx = privdata;
884:     defragPubSubCtx *pubsub_ctx = ctx->privdata;
885:     kvstore *pubsub_channels = pubsub_ctx->pubsub_channels;
886:     robj *newchannel, *channel = dictGetKey(de);
887:     dict *newclients, *clients = dictGetVal(de);
888: 
889:     /* Try to defrag the channel name. */
890:     serverAssert(channel->refcount == (int)dictSize(clients) + 1);
891:     newchannel = activeDefragStringObEx(channel, dictSize(clients) + 1);
892:     if (newchannel) {
893:         kvstoreDictSetKey(pubsub_channels, ctx->slot, (dictEntry*)de, newchannel);
894: 
895:         /* The channel name is shared by the client's pubsub(shard) and server's
896:          * pubsub(shard), after defraging the channel name, we need to update
897:          * the reference in the clients' dictionary. */
898:         dictIterator *di = dictGetIterator(clients);
899:         dictEntry *clientde;
900:         while((clientde = dictNext(di)) != NULL) {
901:             client *c = dictGetKey(clientde);
902:             dictEntry *pubsub_channel = dictFind(pubsub_ctx->clientPubSubChannels(c), newchannel);
903:             serverAssert(pubsub_channel);
904:             dictSetKey(pubsub_ctx->clientPubSubChannels(c), pubsub_channel, newchannel);
905:         }
906:         dictReleaseIterator(di);
907:     }
908: 
909:     /* Try to defrag the dictionary of clients that is stored as the value part. */
910:     if ((newclients = dictDefragTables(clients)))
911:         kvstoreDictSetVal(pubsub_channels, ctx->slot, (dictEntry*)de, newclients);
912: 
913:     server.stat_active_defrag_scanned++;
914: }
