916: /* We may need to defrag other globals, one small allocation can hold a full allocator run.
917:  * so although small, it is still important to defrag these */
918: void defragOtherGlobals(void) {
919: 
920:     /* there are many more pointers to defrag (e.g. client argv, output / aof buffers, etc.
921:      * but we assume most of these are short lived, we only need to defrag allocations
922:      * that remain static for a long time */
923:     activeDefragSdsDict(evalScriptsDict(), DEFRAG_SDS_DICT_VAL_LUA_SCRIPT);
924:     moduleDefragGlobals();
925:     kvstoreDictLUTDefrag(server.pubsub_channels, dictDefragTables);
926:     kvstoreDictLUTDefrag(server.pubsubshard_channels, dictDefragTables);
927: }
