929: /* returns 0 more work may or may not be needed (see non-zero cursor),
930:  * and 1 if time is up and more work is needed. */
931: int defragLaterItem(dictEntry *de, unsigned long *cursor, long long endtime, int dbid) {
932:     if (de) {
933:         robj *ob = dictGetVal(de);
934:         if (ob->type == OBJ_LIST) {
935:             return scanLaterList(ob, cursor, endtime);
936:         } else if (ob->type == OBJ_SET) {
937:             scanLaterSet(ob, cursor);
938:         } else if (ob->type == OBJ_ZSET) {
939:             scanLaterZset(ob, cursor);
940:         } else if (ob->type == OBJ_HASH) {
941:             scanLaterHash(ob, cursor);
942:         } else if (ob->type == OBJ_STREAM) {
943:             return scanLaterStreamListpacks(ob, cursor, endtime);
944:         } else if (ob->type == OBJ_MODULE) {
945:             robj keyobj;
946:             initStaticStringObject(keyobj, dictGetKey(de));
947:             return moduleLateDefrag(&keyobj, ob, cursor, endtime, dbid);
948:         } else {
949:             *cursor = 0; /* object type may have changed since we schedule it for later */
950:         }
951:     } else {
952:         *cursor = 0; /* object may have been deleted already */
953:     }
954:     return 0;
955: }
