961: /* returns 0 if no more work needs to be been done, and 1 if time is up and more work is needed. */
962: int defragLaterStep(redisDb *db, int slot, long long endtime) {
963:     unsigned int iterations = 0;
964:     unsigned long long prev_defragged = server.stat_active_defrag_hits;
965:     unsigned long long prev_scanned = server.stat_active_defrag_scanned;
966:     long long key_defragged;
967: 
968:     do {
969:         /* if we're not continuing a scan from the last call or loop, start a new one */
970:         if (!defrag_later_cursor) {
971:             listNode *head = listFirst(db->defrag_later);
972: 
973:             /* Move on to next key */
974:             if (defrag_later_current_key) {
975:                 serverAssert(defrag_later_current_key == head->value);
976:                 listDelNode(db->defrag_later, head);
977:                 defrag_later_cursor = 0;
978:                 defrag_later_current_key = NULL;
